/* ---------- task index (tasks.html) ---------- */
.group{
  background:var(--card);
  border:1px solid var(--rule);
  border-radius:12px;
  padding:8px 6px;
  box-shadow:0 1px 2px rgba(22,32,46,.04);
  margin-bottom:22px;
}
.group > h2{
  font-family:var(--display); font-weight:600; font-size:1.06rem;
  margin:14px 18px 4px; padding-left:12px;
