  margin:0 18px 12px 34px;
  font-size:.9rem; color:var(--muted);
}
.tasklist{list-style:none; margin:0; padding:0;}
.tasklist li{
  display:flex; align-items:baseline; gap:10px; flex-wrap:wrap;
  padding:9px 18px; border-top:1px solid var(--rule);
}
.tasklist li:hover{background:#FAFBFD;}
.num{
  font-family:var(--mono); font-size:.76rem; color:var(--muted);
  min-width:4.2em; flex:none;
}
.tasklist .title{
  color:var(--ink); text-decoration:none; font-weight:500;
  border-bottom:1px solid transparent; margin-right:auto;
}
.tasklist .title:hover{color:var(--accent); border-bottom-color:#Bcd2f7;}
.q{
  font-family:var(--mono); font-size:.74rem; white-space:nowrap;
  color:var(--accent); text-decoration:none;
  background:var(--accent-soft); border:1px solid #D5E2FB;
  border-radius:5px; padding:1px 7px; flex:none;
}
.q:hover{color:#fff; background:var(--accent); border-color:var(--accent);}
.only{
  font-family:var(--mono); font-size:.72rem; color:var(--muted);
  white-space:nowrap; flex:none;
}

/* ---------- plain link lists (slides page) ---------- */
.linklist{list-style:none; margin:0; padding:0;}
.linklist li{
  display:flex; align-items:baseline; gap:10px; flex-wrap:wrap;
  padding:11px 18px; border-top:1px solid var(--rule);
}
.linklist li:first-child{border-top:0;}
.linklist a{
  color:var(--ink); text-decoration:none; font-weight:500;
  border-bottom:1px solid transparent;
}
.linklist a:hover{color:var(--accent); border-bottom-color:#Bcd2f7;}
.note{font-family:var(--mono); font-size:.74rem; color:var(--muted);}

footer{
  max-width:940px; margin:clamp(40px,6vw,72px) auto 0;
  padding-top:20px; border-top:1px solid var(--rule);
  font-family:var(--mono); font-size:.78rem; color:var(--muted);
}
footer a{color:var(--accent); text-decoration:none;}
footer a:hover{text-decoration:underline;}

:focus-visible{outline:2px solid var(--accent); outline-offset:2px; border-radius:3px;}

@media (max-width:560px){
  body{font-size:16px;}
  .brand{display:none;}
  .navlinks{margin-left:0;}
  .num{min-width:0;}
}
